<?php
declare(strict_types=1);
session_start([
    'cookie_httponly' => true,
    'cookie_samesite' => 'Lax',
]);

// Keep event and activity timestamps in Bayawan City local time regardless
// of the timezone configured on the web server or database host.
date_default_timezone_set('Asia/Manila');

defined('APP_ROOT') || define('APP_ROOT', __DIR__);

// Database configuration — generated by installer on 2026-09-01 05:28:13
const DB_HOST = 'localhost';
const DB_PORT = 3306;
const DB_NAME = 'network_support';
const DB_USER = 'root';
const DB_PASS = '';



function db(): PDO {
    static $pdo;
    if (!$pdo) {
        $pdo = new PDO(
            'mysql:host='.DB_HOST.';port='.DB_PORT.';dbname='.DB_NAME.';charset=utf8mb4',
            DB_USER, DB_PASS,
            [
                PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES   => false,
            ]
        );
        $pdo->exec("SET time_zone = '+08:00'");
    }
    return $pdo;
}
function h(?string $value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function csrf(): string { return $_SESSION['csrf'] ??= bin2hex(random_bytes(32)); }
function verify_csrf(): void {
    if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(419); exit('Invalid request token.'); }
}
function user(): ?array { return $_SESSION['user'] ?? null; }
function is_field_staff(): bool { return in_array(user()['role'] ?? '', ['Network Technician', 'CCS Staff'], true); }
function require_login(): void { if (!user()) { header('Location: login.php'); exit; } }
function allow(array $roles): void { require_login(); if (!in_array(user()['role'], $roles, true)) { http_response_code(403); exit('Access denied.'); } }
function log_activity(string $action, ?int $eventId = null): void {
    if (!user()) return;
    $q = db()->prepare('INSERT INTO activity_logs (user_id, event_id, action, ip_address) VALUES (?,?,?,?)');
    $q->execute([user()['id'], $eventId, $action, $_SERVER['REMOTE_ADDR'] ?? null]);
}
function notify(int $userId, string $message, ?int $eventId = null): void {
    db()->prepare('INSERT INTO notifications (user_id,event_id,message) VALUES (?,?,?)')->execute([$userId,$eventId,$message]);
}
function status_class(string $status): string { return match($status) { 'Completed' => 'success', 'In Progress' => 'primary', 'Assigned','Accepted' => 'info', 'Urgent' => 'danger', 'Cancelled' => 'danger', 'Rescheduled','Pending','Ongoing' => 'warning', default => 'secondary' }; }
